#include "tgcloud/telegram/bot_client.hpp"
#include <curl/curl.h>
namespace tgcloud::telegram { static size_t write_cb(char*p,size_t s,size_t n,void*u){static_cast<std::string*>(u)->append(p,s*n);return s*n;} ApiResponse call(const std::string&u){CURL*c=curl_easy_init();ApiResponse r;if(!c)return r;curl_easy_setopt(c,CURLOPT_URL,u.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,write_cb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&r.body);curl_easy_setopt(c,CURLOPT_TIMEOUT,30L);auto code=curl_easy_perform(c);if(code==CURLE_OK)curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&r.http_status);curl_easy_cleanup(c);return r;} ApiResponse BotClient::get_me()const{return call(base_+"/bot"+token_+"/getMe");} ApiResponse BotClient::get_chat(std::string id)const{return call(base_+"/bot"+token_+"/getChat?chat_id="+id);} }
